const esc=v=>String(v??'NULL').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const trim=(s,n)=>String(s??'NULL').length>n?String(s??'NULL').slice(0,n-1)+'…':String(s??'NULL');
function card(table,title,x,y,width,color,maxRows=4){
 if(!table)return '';
 const columns=table.columns.slice(0,3),rows=table.values.slice(0,maxRows),colWidth=width/columns.length,h=54+rows.length*28+(table.columns.length>3?16:0);
 return `<g transform="translate(${x},${y})"><rect x="4" y="6" width="${width}" height="${h}" rx="8" fill="var(--line)"/><rect width="${width}" height="${h}" rx="8" fill="var(--sheet)" stroke="var(--ink)" stroke-width="1.5"/><path d="M8 0H${width-8}Q${width} 0 ${width} 8V28H0V8Q0 0 8 0Z" fill="${color}"/><text x="12" y="19" font-size="12" font-weight="600">${esc(title)}</text><text x="${width-10}" y="19" text-anchor="end" font-size="10" fill="var(--muted)">${table.values.length} rows</text>${columns.map((c,i)=>`<text x="${i*colWidth+10}" y="46" font-size="10" fill="var(--muted)">${esc(trim(c,14))}</text>`).join('')}${rows.map((r,j)=>`<g class="flow-row" style="animation-delay:${j*120}ms"><path d="M0 ${53+j*28}H${width}" stroke="var(--line)"/>${columns.map((_,i)=>`<text x="${i*colWidth+10}" y="${72+j*28}" font-size="10">${esc(trim(r[i],Math.max(7,Math.floor(colWidth/6))))}</text>`).join('')}</g>`).join('')}${table.columns.length>3?`<text x="${width-6}" y="${h-8}" text-anchor="end" font-size="8" fill="var(--muted)">+${table.columns.length-3} columns</text>`:''}</g>`;
}
export function dataScene(lesson,step,source,result,secondary){
 const phase=step.phase, output=result?.result?.at(-1);if(!source||!output)return '';
 const join=phase==='join'&&secondary;
 let operation={filter:'WHERE',project:'SELECT',join:'JOIN',group:'GROUP BY',sort:'ORDER BY'}[phase]||'QUERY';
 if(/\bUPDATE\b/.test(step.query))operation='UPDATE';else if(/\bDELETE\b/.test(step.query))operation='DELETE';else if(/\bOVER\s*\(/.test(step.query))operation='WINDOW';else if(/\bEXPLAIN\b/.test(step.query))operation='PLAN';else if(/\bDISTINCT\b/.test(step.query))operation='DISTINCT';else if(/\bHAVING\b/.test(step.query))operation='HAVING';
 const caption={WHERE:'Keep the rows that satisfy the condition.',SELECT:'Choose the columns that answer your question.',JOIN:'Match related rows using a shared key.','GROUP BY':'Collect related rows, then calculate each group.','ORDER BY':'Arrange the answer in a meaningful order.',UPDATE:'Change selected values in a fresh sandbox.',DELETE:'Remove matching rows in a fresh sandbox.',WINDOW:'Calculate across rows without collapsing them.',PLAN:'Inspect the strategy SQLite chooses.',DISTINCT:'Return each distinct combination once.',HAVING:'Keep the groups that satisfy the condition.'}[operation]||'Follow the data into the result set.';
 if(matchMedia('(max-width:760px)').matches)return `<svg class="diagram data-diagram mobile-data" viewBox="0 0 360 475" role="img" aria-label="${esc(operation)} transforms source data into a result set">${card(source,lesson.source,20,8,315,'var(--violet)',3)}<path d="M180 150V203M180 249V294" class="wire active"/><rect x="114" y="203" width="132" height="46" rx="9" fill="var(--green)" stroke="var(--ink)"/><text x="180" y="232" font-size="13" text-anchor="middle" font-weight="600">${operation}</text>${join?`<text x="180" y="276" font-size="10" text-anchor="middle">+ ${esc(secondary.name)} through matching keys</text>`:''}${card(output,'query result',20,294,315,'var(--green)',3)}<circle r="4" fill="#b3cb91"><animateMotion dur="2s" repeatCount="indefinite" path="M180 150V203"/></circle></svg>`;
 return `<svg class="diagram data-diagram" viewBox="0 0 900 360" role="img" aria-label="${esc(operation)} transforms ${source.values.length} source rows into ${output.values.length} result rows"><defs><pattern id="data-grid" width="40" height="24" patternUnits="userSpaceOnUse"><path d="M0 0L40 24M40 0L0 24" stroke="var(--line)" stroke-width=".8" fill="none" opacity=".35"/></pattern></defs><rect width="900" height="360" fill="url(#data-grid)" opacity=".5"/>
 ${card(source,lesson.source,20,join?25:93,280,'var(--violet)',join?2:4)}${join?card(secondary.table,secondary.name,20,205,280,'var(--orange)',2):''}
 <path class="wire active" d="M300 ${join?90:178}C350 ${join?90:178} 350 178 390 178M510 178H590${join?'M300 270C350 270 350 178 390 178':''}"/>
 <g transform="translate(388,131)"><rect x="4" y="5" width="124" height="90" rx="12" fill="var(--line)"/><rect width="124" height="90" rx="12" fill="var(--green)" stroke="var(--ink)" stroke-width="1.5"/><path d="M47 20h30l-10 13v13l-10-5v-8z" fill="var(--sheet)" stroke="var(--ink)" stroke-width="1.4"/><text x="62" y="70" text-anchor="middle" font-size="12" font-weight="600">${operation}</text></g>
 ${card(output,'query result',590,93,285,'var(--green)',4)}
 <circle r="5" fill="#dbb286" stroke="var(--ink)"><animateMotion dur="3s" repeatCount="indefinite" path="M300 ${join?90:178}C350 ${join?90:178} 350 178 390 178"/></circle><circle r="5" fill="#a2bc7d" stroke="var(--ink)"><animateMotion dur="2.5s" repeatCount="indefinite" path="M510 178H590"/></circle>
 <text x="450" y="330" text-anchor="middle" font-size="11" fill="var(--muted)">${esc(caption)}</text></svg>`;
}
